<?php $pageTitle='Product details | HEX CHEATS SHOP';$activePage='shop';$productKey=(string)($_GET['product_key']??'');require __DIR__.'/_head.php'; ?>
<section class="hx-page-heading"><p class="hx-eyebrow">PRODUCT DETAILS</p><h1>Choose your access</h1></section><section id="productDetail" class="hx-panel hx-loading">Loading product…</section>
<script>(()=>{const key=<?=json_encode($productKey,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,box=document.getElementById('productDetail'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=(value,symbol)=>{const n=Number(String(value??'').replace(/[^0-9.\-]/g,''));return Number.isFinite(n)?symbol+n.toFixed(2):'Price unavailable'};fetch('/api/store/products').then(r=>r.json()).then(d=>{const p=(d.products||[]).find(x=>x.key===key);if(!p){box.textContent='This product is unavailable.';return}box.classList.remove('hx-loading');const durations=p.durations||[],next='/product/'+encodeURIComponent(key);box.innerHTML=`${p.image_url?`<img class="hx-detail-image" src="${esc(p.image_url)}" alt="${esc(p.name)}">`:''}<p class="hx-eyebrow">${esc(p.category||'Digital access')} · ${esc(p.platform||'')}</p><h2>${esc(p.name)}</h2><p>${esc(p.description||'Choose a duration to see its price.')}</p><label class="hx-label">Duration<select id="duration">${durations.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><div id="priceList" class="hx-price-list"></div>${p.demo_url?`<a class="hx-button hx-secondary" href="${esc(p.demo_url)}" target="_blank" rel="noopener noreferrer">Watch demo</a>`:''}${p.download_url?`<a class="hx-button hx-secondary" href="${esc(p.download_url)}" target="_blank" rel="noopener noreferrer">Open download / setup</a>`:''}<a class="hx-button" href="/login?next=${encodeURIComponent(next)}">Sign in to buy</a>`;const $=id=>document.getElementById(id),draw=()=>{$('priceList').innerHTML=durations.map(x=>`<div class="hx-row"><span>${esc(x)}</span><b>${money(p.prices?.[x],'₹')}${p.usd_prices?.[x]?' · '+money(p.usd_prices[x],'$'):''}</b></div>`).join('')};draw();$('duration').onchange=draw}).catch(()=>box.textContent='Could not load product details. Please try again.')})();</script>
<?php require __DIR__.'/_foot.php'; ?>
